// The requisition returns an array of account IDs.
// Fan them out so each account is fetched independently — one failing
// account must not take down the whole sync.
const requisition = $input.first().json;
const accounts = requisition.accounts || [];

if (accounts.length === 0) {
  throw new Error(
    'No accounts on this requisition. The bank consent has probably expired — ' +
    'GoCardless consents last 90 days and must be re-authorised. Re-run the link flow.'
  );
}

return accounts.map(id => ({ json: { account_id: id } }));

// ---------------------------------------------------------------------
// Normalise the provider payload into rows our schema understands, and
// build idempotent upsert SQL.
//
// Merchant normalisation is the load-bearing part of this whole system:
// subscription detection groups by merchant_key, so if normalisation is
// sloppy the radar sees ten merchants where there is one.
// ---------------------------------------------------------------------

const accountId = $('Loop Accounts').first().json.account_id;
const txPayload = $('Get Transactions').first().json || {};
const balPayload = $('Get Balances').first().json || {};

function sqlEscape(value) {
  if (value === null || value === undefined) return 'NULL';
  return "'" + String(value).replace(/'/g, "''") + "'";
}

function normaliseMerchant(description) {
  return String(description || 'unknown')
    .toLowerCase()
    // Card-scheme noise that varies per transaction.
    .replace(/\b(card|visa|mastercard|contactless|pos|atm|ref|reference)\b/g, ' ')
    // Dates in any common shape.
    .replace(/\b\d{1,2}[\/-]\d{1,2}([\/-]\d{2,4})?\b/g, ' ')
    // Long digit runs: card fragments, transaction ids, store numbers.
    .replace(/\b\d{3,}\b/g, ' ')
    // Trailing store/branch identifiers, e.g. "TESCO 4823".
    .replace(/[^a-z\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    // Keep the first three meaningful words — enough to identify a
    // merchant, short enough to survive their formatting changes.
    .split(' ')
    .filter(w => w.length > 1)
    .slice(0, 3)
    .join(' ') || 'unknown';
}

// GoCardless splits booked (settled) and pending. Only booked is trustworthy
// for recurring-payment detection — pending amounts and descriptions change.
const booked = (txPayload.transactions && txPayload.transactions.booked) || [];

const rows = booked.map(tx => {
  const description =
    tx.remittanceInformationUnstructured ||
    (tx.remittanceInformationUnstructuredArray || []).join(' ') ||
    (tx.creditorName || tx.debtorName) ||
    'unknown';

  const amount = parseFloat((tx.transactionAmount && tx.transactionAmount.amount) || '0');

  return {
    provider_tx_id: tx.internalTransactionId || tx.transactionId || `${tx.bookingDate}-${amount}-${description}`.slice(0, 120),
    account_id: accountId,
    booked_at: tx.bookingDate || tx.valueDate,
    amount_gbp: amount,
    currency: (tx.transactionAmount && tx.transactionAmount.currency) || 'GBP',
    raw_description: description,
    merchant_key: normaliseMerchant(description),
  };
}).filter(r => r.booked_at);

// ------- transaction upsert -------
// ON CONFLICT DO NOTHING makes re-polling free: the provider always
// re-sends the last ~90 days, and we only ever want the new ones.
let txSql = 'SELECT 1;';
if (rows.length > 0) {
  const values = rows.map(r => `(${[
    sqlEscape(r.provider_tx_id),
    sqlEscape(r.account_id),
    sqlEscape(r.booked_at),
    Number.isFinite(r.amount_gbp) ? r.amount_gbp : 0,
    sqlEscape(r.currency),
    sqlEscape(r.raw_description),
    sqlEscape(r.merchant_key),
  ].join(', ')})`).join(',\n  ');

  txSql = `INSERT INTO money.transactions
  (provider_tx_id, account_id, booked_at, amount_gbp, currency, raw_description, merchant_key)
VALUES
  ${values}
ON CONFLICT (account_id, provider_tx_id) DO NOTHING;`;
}

// ------- balance upsert -------
// Prefer the interim available balance; fall back to whatever is present.
const balances = balPayload.balances || [];
const preferred =
  balances.find(b => b.balanceType === 'interimAvailable') ||
  balances.find(b => b.balanceType === 'closingBooked') ||
  balances[0];

let balSql = 'SELECT 1;';
if (preferred && preferred.balanceAmount) {
  const amt = parseFloat(preferred.balanceAmount.amount || '0');
  balSql = `INSERT INTO money.balances (account_id, balance_gbp, updated_at)
VALUES (${sqlEscape(accountId)}, ${Number.isFinite(amt) ? amt : 0}, now())
ON CONFLICT (account_id) DO UPDATE
  SET balance_gbp = EXCLUDED.balance_gbp,
      updated_at  = now();`;
}

return [{
  json: {
    account_id: accountId,
    row_count: rows.length,
    tx_sql: txSql,
    bal_sql: balSql,
  }
}];
